  ]'::jsonb;
  
  item jsonb;
BEGIN
  FOR item IN SELECT * FROM jsonb_array_elements(trans_data)
  LOOP
    -- Insert English
    INSERT INTO public.ui_translations (id, key, locale, value) 
    VALUES (gen_random_uuid(), item->>'key', 'en', item->>'en')
    ON CONFLICT (key, locale) DO UPDATE SET value = EXCLUDED.value;
    
    -- Insert Portuguese
    INSERT INTO public.ui_translations (id, key, locale, value) 
    VALUES (gen_random_uuid(), item->>'key', 'pt', item->>'pt')
    ON CONFLICT (key, locale) DO UPDATE SET value = EXCLUDED.value;
    
    -- Insert Spanish
    INSERT INTO public.ui_translations (id, key, locale, value) 
    VALUES (gen_random_uuid(), item->>'key', 'es', item->>'es')
    ON CONFLICT (key, locale) DO UPDATE SET value = EXCLUDED.value;
  END LOOP;
END $$;
